static enum bufferevent_filter_result bufferevent_input_filter ( struct evbuffer * src , struct evbuffer * dst , ev_ssize_t lim , enum bufferevent_flush_mode state , void * ctx ) { const unsigned char * buffer ; unsigned i ; buffer = evbuffer_pullup ( src , evbuffer_get_length ( src ) ) ; for ( i = 0 ; i < evbuffer_get_length ( src ) ; i += 2 ) { assert ( buffer [ i ] == 'x' ) ; evbuffer_add ( dst , buffer + i + 1 , 1 ) ; if ( i + 2 > evbuffer_get_length ( src ) ) { break ; } } return ( BEV_OK ) ; } 